-- QuantBet shadow/research layer: exposure-only value signals.
--
-- This table stores only the missing research fact. Immutable value, prediction,
-- fixture and quote facts remain normalized in their existing tables.

CREATE TABLE research_signals (
    research_signal_id TEXT PRIMARY KEY
        CHECK (research_signal_id ~ '^research-signal-v1:[0-9a-f]{64}$'),
    evaluation_id TEXT NOT NULL UNIQUE
        REFERENCES value_evaluations(evaluation_id) ON DELETE RESTRICT,
    stage TEXT NOT NULL CHECK (stage = 'PRELIMINARY'),
    block_reason TEXT NOT NULL
        CHECK (block_reason = 'MAX_OPEN_EXPOSURE_EXCEEDED'),
    first_blocked_at TIMESTAMPTZ NOT NULL,
    last_blocked_at TIMESTAMPTZ NOT NULL,
    blocked_count BIGINT NOT NULL CHECK (blocked_count > 0),
    first_open_exposure_minor BIGINT NOT NULL CHECK (first_open_exposure_minor >= 0),
    last_open_exposure_minor BIGINT NOT NULL CHECK (last_open_exposure_minor >= 0),
    exposure_cap_minor BIGINT NOT NULL CHECK (exposure_cap_minor > 0),
    persisted_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (last_blocked_at >= first_blocked_at)
);

CREATE INDEX idx_research_signals_last_blocked
    ON research_signals (last_blocked_at DESC, evaluation_id);
CREATE INDEX idx_research_signals_block_reason
    ON research_signals (block_reason, last_blocked_at DESC);

