INSERT INTO research_signals (
    research_signal_id,
    evaluation_id,
    stage,
    block_reason,
    first_blocked_at,
    last_blocked_at,
    blocked_count,
    first_open_exposure_minor,
    last_open_exposure_minor,
    exposure_cap_minor
)
SELECT
    'research-signal-v1:' || split_part(b.evaluation_id, ':', 2),
    b.evaluation_id,
    'PRELIMINARY',
    'MAX_OPEN_EXPOSURE_EXCEEDED',
    b.first_blocked_at,
    b.last_blocked_at,
    b.blocked_count,
    b.first_open_exposure_minor,
    b.last_open_exposure_minor,
    b.exposure_cap_minor
FROM backfill b
JOIN value_evaluations e ON e.evaluation_id = b.evaluation_id
ON CONFLICT (evaluation_id) DO UPDATE SET
    first_open_exposure_minor = CASE
        WHEN EXCLUDED.first_blocked_at < research_signals.first_blocked_at
        THEN EXCLUDED.first_open_exposure_minor
        ELSE research_signals.first_open_exposure_minor
    END,
    last_open_exposure_minor = CASE
        WHEN EXCLUDED.last_blocked_at >= research_signals.last_blocked_at
        THEN EXCLUDED.last_open_exposure_minor
        ELSE research_signals.last_open_exposure_minor
    END,
    first_blocked_at = LEAST(
        research_signals.first_blocked_at, EXCLUDED.first_blocked_at
    ),
    last_blocked_at = GREATEST(
        research_signals.last_blocked_at, EXCLUDED.last_blocked_at
    ),
    blocked_count = research_signals.blocked_count + EXCLUDED.blocked_count,
    exposure_cap_minor = EXCLUDED.exposure_cap_minor;
